/**
 * Button (issue #11) — the first Augur-owned component.
 *
 * shadcn-compatible API, Augur-owned styling: a native `<button>`
 * styled exclusively through the semantic role custom properties
 * delivered by `@augur/design-system/styles.css` (see `./button.css`).
 * React 19 style: a plain function component; `ref` forwards through
 * props (no forwardRef).
 *
 * Contracts (consumer view: docs "Button" page; decision record:
 * `docs/components.md` in this package):
 *
 *   - `type` defaults to "button" — a deliberate deviation from
 *     upstream shadcn, which leaves the browser's "submit" default.
 *     Forms opt into submission explicitly.
 *   - Disabled: native `disabled`, reduced-contrast but present label,
 *     `cursor: not-allowed` (the FD-06 Proposed treatment).
 *   - Loading (`loading`): non-interactive, `aria-busy="true"`, label
 *     kept in the DOM but hidden from eyes and assistive technology so
 *     the button keeps its width; a reduced-motion-safe spinner and a
 *     visually hidden "Loading" status carry the state. The action
 *     color does not change.
 *
 * Keyboard focus needs no CSS here: the theme contract's shared
 * `:focus-visible` rule (2px ring, 2px offset, `--ring` color) applies
 * to every element, including this one.
 */

import "./button.css";
import type { ComponentProps } from "react";
import type { ButtonSize, ButtonVariant } from "./button-variants";
import { buttonVariants } from "./button-variants";
import { cx } from "@/lib/utils";

export { buttonVariants } from "./button-variants";

export type ButtonProps = ComponentProps<"button"> & {
  /** Visual intent. The default variant is the view's one green signal. */
  variant?: ButtonVariant;
  /** Control size (FD-02 Proposed heights). Default "md". */
  size?: ButtonSize;
  /** Pending state: non-interactive, width-preserving, aria-busy. */
  loading?: boolean;
};

export function Button({
  variant,
  size,
  loading = false,
  disabled = false,
  type,
  className,
  children,
  ...props
}: ButtonProps) {
  return (
    <button
      {...props}
      type={type ?? "button"}
      disabled={disabled || loading}
      aria-busy={loading || undefined}
      className={cx(buttonVariants({ variant, size }), className)}
    >
      <span className="aug-button-label" aria-hidden={loading || undefined}>
        {children}
      </span>
      {loading ? (
        <span className="aug-button-spinner" aria-hidden="true">
          <svg
            className="aug-button-spinner-icon"
            viewBox="0 0 16 16"
            width="16"
            height="16"
            aria-hidden="true"
          >
            <circle
              cx="8"
              cy="8"
              r="6.5"
              fill="none"
              stroke="currentColor"
              strokeWidth="2"
              strokeLinecap="round"
              strokeDasharray="29 12"
            />
          </svg>
        </span>
      ) : null}
      {loading ? <span className="aug-button-visually-hidden">Loading</span> : null}
    </button>
  );
}

/**
 * Variant and size class mapping for Button (issue #11).
 *
 * Augur owns this API but keeps it shadcn-shaped: `buttonVariants` is
 * the plain-function analog of the upstream `cva` call — callable with
 * `{ variant, size }` and returning the full class string, including
 * the control typography role, so class-only consumers (and the future
 * registry source path, issue #16) get the same result by applying the
 * classes to a native `<button>`. No class-variance-authority
 * dependency: the matrix is small and the package's runtime
 * dependencies stay at the font packages.
 *
 * Classes resolve color exclusively through the semantic role custom
 * properties in `src/styles/theme.css`. Geometry values in
 * `button.css` are structural constants aligned with the FD-01, FD-02,
 * and FD-03 foundation proposals (Proposed — pending maintainer
 * review), not emitted tokens; see `docs/components.md` in this
 * package for the decision record.
 */

/** Visual intent of the button. shadcn-compatible set, Augur-owned. */
export type ButtonVariant =
  | "default"
  | "secondary"
  | "destructive"
  | "outline"
  | "ghost"
  | "link";

/** Control size. Heights follow the FD-02 proposal (Proposed). */
export type ButtonSize = "sm" | "md" | "lg";

export interface ButtonVariantsProps {
  variant?: ButtonVariant;
  size?: ButtonSize;
}

const VARIANT_CLASSES: Record<ButtonVariant, string> = {
  default: "aug-button--default",
  secondary: "aug-button--secondary",
  destructive: "aug-button--destructive",
  outline: "aug-button--outline",
  ghost: "aug-button--ghost",
  link: "aug-button--link",
};

const SIZE_CLASSES: Record<ButtonSize, string> = {
  sm: "aug-button--sm",
  md: "aug-button--md",
  lg: "aug-button--lg",
};

/** Full class string for the given variant and size (defaults: md). */
export function buttonVariants(props: ButtonVariantsProps = {}): string {
  const variant = props.variant ?? "default";
  const size = props.size ?? "md";
  return `aug-button augur-type-control ${VARIANT_CLASSES[variant]} ${SIZE_CLASSES[size]}`;
}

/*
 * Button styles (issue #11).
 *
 * Color: ONLY semantic role custom properties from ../../styles/theme.css
 * (which references generated tokens). No raw color values, no new
 * custom properties.
 *
 * Geometry: intentional structural constants — FD-01 (spacing), FD-02
 * (control heights), and FD-03 (radius) are Proposed and pending
 * maintainer review, so no spacing/radius/sizing tokens are emitted;
 * the same pattern the FD-04 ring geometry uses in theme.css. The
 * decision record for this slice lives in ../../docs/components.md.
 */

.aug-button {
  position: relative;
  box-sizing: border-box;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 8px; /* FD-01 space.sm (Proposed): label-to-icon gap */
  height: 36px; /* FD-02 control.height.md (Proposed) */
  padding: 0 16px; /* FD-01: md control padding (Proposed) */
  margin: 0;
  border: 1px solid transparent; /* keeps the box equal across variants */
  border-radius: 6px; /* FD-03 radius.control (Proposed) */
  vertical-align: middle;
  white-space: nowrap;
  cursor: pointer;
  text-decoration: none;
  background-color: var(--primary);
  color: var(--primary-foreground);
}

/* Sizes: FD-01/FD-02 Proposed values as structure (sm 32/12, lg 40/24). */
.aug-button--sm {
  height: 32px;
  padding: 0 12px;
}

.aug-button--lg {
  height: 40px;
  padding: 0 24px;
}

/*
 * Filled variants. default = action-primary pairing (Deep + White
 * light, Green + Navy dark — the view's one green signal); secondary
 * sits on the quiet surface; destructive uses the strongest neutral
 * pairing (theme decision D1: the brand defines no danger hue, so the
 * label carries the meaning).
 */
.aug-button--secondary {
  background-color: var(--secondary);
  color: var(--secondary-foreground);
}

.aug-button--destructive {
  background-color: var(--destructive);
  color: var(--destructive-foreground);
}

/* Surface variants: quiet by default; the theme's neutral
   hover/highlight surface (accent) on hover. */
.aug-button--outline {
  background-color: transparent;
  border-color: var(--input);
  color: var(--foreground);
}

.aug-button--ghost {
  background-color: transparent;
  color: var(--foreground);
}

/* Link: quiet text action. Deliberately NOT action-colored — a view
   has one green signal (primary action, focus), and text links are not
   it (decision D3 in docs/components.md). */
.aug-button--link {
  background-color: transparent;
  color: var(--foreground);
}

/*
 * Hover/pressed (FD-06 Proposed interaction treatment, decision D2):
 *   - filled variants: a subtle tint of their own color — the
 *     plain-CSS form of the shadcn `bg-primary/90` convention — pressed
 *     one step further down the same ladder;
 *   - surface variants: the accent surface, pressed one step back
 *     toward the canvas;
 *   - link: the underline appears.
 * color-mix only mixes existing roles with transparency; no colors are
 * invented. Hover/pressed never apply to disabled buttons.
 */
.aug-button--default:hover:not(:disabled),
.aug-button--destructive:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--primary) 90%, transparent);
}

.aug-button--default:active:not(:disabled),
.aug-button--destructive:active:not(:disabled) {
  background-color: color-mix(in srgb, var(--primary) 80%, transparent);
}

.aug-button--secondary:hover:not(:disabled) {
  background-color: color-mix(in srgb, var(--secondary) 90%, transparent);
}

.aug-button--secondary:active:not(:disabled) {
  background-color: color-mix(in srgb, var(--secondary) 80%, transparent);
}

.aug-button--outline:hover:not(:disabled),
.aug-button--ghost:hover:not(:disabled) {
  background-color: var(--accent);
  color: var(--accent-foreground);
}

.aug-button--outline:active:not(:disabled),
.aug-button--ghost:active:not(:disabled) {
  background-color: color-mix(in srgb, var(--accent) 70%, transparent);
}

.aug-button--link:hover:not(:disabled) {
  text-decoration: underline;
  text-underline-offset: 0.2em;
  text-decoration-thickness: 2px;
}

/*
 * Disabled (FD-06 Proposed, decision D5): non-interactive via the
 * native attribute, reduced-contrast label that remains present and
 * readable in the DOM, never color-alone. WCAG 1.4.3 exempts disabled
 * controls from contrast minimums.
 */
.aug-button:disabled {
  cursor: not-allowed;
  opacity: 0.5;
}

/*
 * Loading (decision D6): the label stays in the DOM (width preserved)
 * but is hidden from eyes and assistive technology; the spinner
 * overlays, centered; the accessible name becomes the visually hidden
 * "Loading" status rendered by the component.
 */
.aug-button[aria-busy="true"] .aug-button-label {
  visibility: hidden;
}

.aug-button-spinner {
  position: absolute;
  inset: 0;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  pointer-events: none;
}

.aug-button-spinner-icon {
  display: block;
  /* Structural rotation (16px inline icon size, FD-02 Proposed); no
     motion token exists (FD-05 Proposed). The package reduced-motion
     gate collapses this to a static arc. */
  animation: aug-button-spin 0.8s linear infinite;
}

@keyframes aug-button-spin {
  to {
    transform: rotate(360deg);
  }
}

/* Visually hidden loading status (component-scoped utility). */
.aug-button-visually-hidden {
  position: absolute;
  width: 1px;
  height: 1px;
  margin: -1px;
  padding: 0;
  overflow: hidden;
  clip-path: inset(50%);
  white-space: nowrap;
  border: 0;
}
